        except Exception:
            if writing: raise WriteOutcomeUnknown(key=key) from None
            raise
        if refusal is not None:
            if isinstance(refusal, WriteOutcomeUnknown): refusal.key = key
            raise refusal
        return result
    def key(self, record: str, value: Any) -> dict[str, Any]:
