                           else wire_error(response['error']))
            else:
                refusal = None
                if writing and response.get('status', 'committed') != 'committed': raise AccessError('INVALID_RESPONSE')
            result = dict(response)
        except Exception:
            if writing: raise WriteOutcomeUnknown(key=key) from None
            raise
